import json, time, urllib.request, urllib.error

API_BASE = 'https://api.ivxholding.com'
OWNER_EMAIL = 'iperez4242@gmail.com'
EMERGENCY = 'ivx_emergency_recovery'
CONVERSATION_ID = f'ivx-ia-v6-debug-{int(time.time())}'

def api_call(path, payload, token=None):
    url = f'{API_BASE}{path}'
    body = json.dumps(payload).encode('utf8')
    req = urllib.request.Request(url, data=body, headers={'Content-Type': 'application/json'}, method='POST')
    if token:
        req.add_header('Authorization', f'Bearer {token}')
    try:
        with urllib.request.urlopen(req, timeout=60) as resp:
            return resp.status, json.loads(resp.read().decode('utf8'))
    except urllib.error.HTTPError as e:
        try:
            return e.code, json.loads(e.read().decode('utf8'))
        except Exception:
            return e.code, {'error': e.reason}

status, data = api_call('/api/ivx/owner-passwordless-login', {'email': OWNER_EMAIL, 'emergency': EMERGENCY})
if status != 200 or not data.get('accessToken'):
    print('Login failed', status, data)
    exit(1)
token = data['accessToken']

messages = [
    '¿Cuántas propiedades tenemos?',
    '¿Dónde nos quedamos?',
    'show me the last 5 properties',
    'how many active properties do we have',
]

for msg in messages:
    print(f'\n=== {msg} ===')
    s, d = api_call('/api/ivx/owner-ai', {
        'message': msg,
        'conversationId': CONVERSATION_ID,
        'devTestModeActive': False,
    }, token)
    print(f'status={s}')
    for k in ['answer', 'provider', 'source', 'selectedIntent', 'selectedTool', 'endpoint', 'deploymentMarker']:
        if k in d:
            print(f'{k}: {d[k] if k != "answer" else d[k][:200]}')
    if 'error' in d:
        print('error:', d['error'])
    print('toolOutputs:', json.dumps(d.get('toolOutputs', []), indent=2, default=str)[:500])
