#!/usr/bin/env python3
"""Apply V6.2 conversation state fixes: context-aware classification, approval-first flow, task_status regex."""
import re

STATE_FILE = '/home/user/rork-app/backend/services/ivx-owner-conversation-state.ts'
AI_FILE = '/home/user/rork-app/backend/api/ivx-owner-ai.ts'

# 1. Update OwnerConversationState to add readOnlyAuthorized.
with open(STATE_FILE, 'r', encoding='utf-8') as f:
    state_content = f.read()

state_content = state_content.replace(
    "  lastVerifiedProductionState: Record<string, unknown> | null;\n};",
    "  lastVerifiedProductionState: Record<string, unknown> | null;\n  readOnlyAuthorized: boolean;\n};"
)

# 2. Update default state to include readOnlyAuthorized: false.
state_content = state_content.replace(
    "    lastVerifiedProductionState: null,\n  };\n}\n\nexport async function getOwnerConversationState",
    "    lastVerifiedProductionState: null,\n    readOnlyAuthorized: false,\n  };\n}\n\nexport async function getOwnerConversationState"
)

# 3. Fix task_status regex (remove \b for accented phrases).
state_content = state_content.replace(
    "  if (/\\b(estado|status|where are we|where were we|dónde nos quedamos|donde nos quedamos|qué estabas haciendo|que estabas haciendo|what were you doing)\\b/i.test(normalized)) {",
    "  if (/(estado|status|where are we|where were we|dónde nos quedamos|donde nos quedamos|qué estabas haciendo|que estabas haciendo|what were you doing|dónde quedamos|donde quedamos)/i.test(normalized)) {"
)

# 4. Remove 'information' from isReadOnlyActionType so generic questions fall through to LLM.
state_content = state_content.replace(
    "export function isReadOnlyActionType(actionType: OwnerActionType): boolean {\n  return actionType === 'database_read' || actionType === 'database_read_active' || actionType === 'database_list_latest' || actionType === 'information' || actionType === 'explanation' || actionType === 'task_status';\n}",
    "export function isReadOnlyActionType(actionType: OwnerActionType): boolean {\n  return actionType === 'database_read' || actionType === 'database_read_active' || actionType === 'database_list_latest' || actionType === 'explanation' || actionType === 'task_status';\n}"
)

# 5. Add classifyOwnerActionTypeWithContext helper after classifyOwnerActionType.
helper = """
export function classifyOwnerActionTypeWithContext(
  message: string,
  previousAction: PendingOwnerAction | null,
): { actionType: OwnerActionType; resource: string | null; operation: string | null; metadata: Record<string, unknown> } {
  const classified = classifyOwnerActionType(message);
  if (classified.resource === 'properties' || classified.resource === 'deals' || classified.actionType === 'database_read' || classified.actionType === 'database_read_active' || classified.actionType === 'database_list_latest') {
    return classified;
  }
  if ((classified.actionType === 'information' || classified.actionType === 'unknown') && previousAction && (previousAction.resource === 'properties' || previousAction.resource === 'deals')) {
    const normalized = asTrimmedString(message).toLowerCase();
    const wantsActive = /\\b(activas?|activos?|active|activo|en\\s*venta|for\\s+sale|available|disponible|disponibles|live|published)\\b/i.test(normalized);
    const wantsLatest = /\\b(últimas?|ultimas?|últimos?|ultimos?|latest|recent|recientes|last\\s+five|last\\s+5|últimas\\s+cinco|ultimas\\s+cinco|muéstrame|muestrame|show\\s+me|list)\\b/i.test(normalized);
    const listLimitMatch = normalized.match(/\\b(\\d+)\\b/);
    const listLimit = listLimitMatch ? Math.min(Math.max(Number(listLimitMatch[1]), 1), 100) : 5;
    if (wantsActive) return { actionType: 'database_read_active', resource: 'properties', operation: 'count_active', metadata: {} };
    if (wantsLatest) return { actionType: 'database_list_latest', resource: 'properties', operation: 'select_latest', metadata: { limit: listLimit } };
    return { actionType: 'database_read', resource: 'properties', operation: 'count', metadata: {} };
  }
  return classified;
}

"""

# Insert helper after the classifyOwnerActionType function.
marker = "export function isReadOnlyActionType(actionType: OwnerActionType): boolean {"
if marker in state_content and 'classifyOwnerActionTypeWithContext' not in state_content:
    state_content = state_content.replace(marker, helper + marker)

with open(STATE_FILE, 'w', encoding='utf-8') as f:
    f.write(state_content)

print('Updated', STATE_FILE)

# 6. Update ivx-owner-ai.ts state machine to use the new classification and approval flow.
with open(AI_FILE, 'r', encoding='utf-8') as f:
    ai_content = f.read()

# Replace the import to include classifyOwnerActionTypeWithContext.
ai_content = ai_content.replace(
    "import {\n  addPendingAction,\n  buildWhereWeWereSummary,\n  classifyOwnerActionType,\n  detectOwnerApproval,\n  executeReadOnlyAction,\n  getActiveAction,\n  getOwnerConversationState,\n  isReadOnlyActionType,\n  resolveActiveAction,\n  setOwnerConversationState,\n  updateAction,\n  type OwnerActionType,\n} from '../services/ivx-owner-conversation-state';",
    "import {\n  addPendingAction,\n  buildWhereWeWereSummary,\n  classifyOwnerActionTypeWithContext,\n  detectOwnerApproval,\n  executeReadOnlyAction,\n  getActiveAction,\n  getOwnerConversationState,\n  isReadOnlyActionType,\n  resolveActiveAction,\n  setOwnerConversationState,\n  updateAction,\n  type OwnerActionType,\n} from '../services/ivx-owner-conversation-state';"
)

# Update the approval resolution block to set readOnlyAuthorized: true and use the previous action.
old_approval = """    // 1. Approval / denial resolution for a pending action.
    if (approvalSignal !== 'neutral' && activeAction) {
      const resolvedStatus = approvalSignal === 'approve' ? 'granted' : 'denied';
      const resolved = await resolveActiveAction(conversation.id, ownerContext.userId, resolvedStatus);
      if (resolved) {
        if (resolvedStatus === 'denied') {
          await updateAction(conversation.id, ownerContext.userId, resolved.actionId, {
            executionState: 'CANCELLED',
            lastResultSummary: 'Owner denied.',
            updatedAt: nowIso(),
          });
          await setOwnerConversationState({ ...ownerState, activeActionId: null, unresolvedQuestion: null });
          const deniedAnswer = detectedLang === 'es' ? 'Acción cancelada.' : 'Action cancelled.';
          return returnStateAnswer(deniedAnswer, { actionId: resolved.actionId, authorizationStatus: 'denied' });
        }
        if (isReadOnlyActionType(resolved.actionType)) {
          const result = await executeReadOnlyAction(resolved);
          await updateAction(conversation.id, ownerContext.userId, resolved.actionId, {
            executionState: result.ok ? 'COMPLETED' : 'FAILED',
